using Dapper;
using MdwConteudos.Api.Infrastructure;

namespace MdwConteudos.Api.Modules.Automacoes;

public static class ChatfastSchema
{
    public static readonly IReadOnlyDictionary<string, string> Definitions = new Dictionary<string, string>
    {
        ["CHATFASTRESPOSTA"] = "CODCHATFASTRESPOSTA BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, CHAVE VARCHAR(64) CHARACTER SET ASCII NOT NULL, SHA256 VARCHAR(64) CHARACTER SET ASCII NOT NULL, ORIGEM VARCHAR(20) CHARACTER SET ASCII NOT NULL, DTHRRESPOSTA TIMESTAMP, DTHRCRIACAO TIMESTAMP NOT NULL, CODCHATFASTIMPORTACAO BIGINT, LINHA INTEGER, DOCUMENTO BLOB SUB_TYPE TEXT CHARACTER SET UTF8 NOT NULL, CONSTRAINT PK_CHATFASTRESPOSTA PRIMARY KEY(CODCHATFASTRESPOSTA), CONSTRAINT UNQ_CFRESPOSTA_CHAVE UNIQUE(CHAVE)",
        ["CHATFASTRESPOSTAITEM"] = "CODCHATFASTRESPOSTA BIGINT NOT NULL, POSICAO INTEGER NOT NULL, CODIGOEXTERNO VARCHAR(120) CHARACTER SET UTF8 NOT NULL, TRATADO SMALLINT NOT NULL, CONSTRAINT PK_CFRESPOSTAITEM PRIMARY KEY(CODCHATFASTRESPOSTA,POSICAO), CONSTRAINT FK_CFITEM_RESPOSTA FOREIGN KEY(CODCHATFASTRESPOSTA) REFERENCES CHATFASTRESPOSTA(CODCHATFASTRESPOSTA), CONSTRAINT CK_CFITEM_TRATADO CHECK(TRATADO IN (0,1))",
        ["CHATFASTIMPORTACAO"] = "CODCHATFASTIMPORTACAO BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, SHA256 VARCHAR(64) CHARACTER SET ASCII NOT NULL, NOMEARQUIVO VARCHAR(255) CHARACTER SET UTF8 NOT NULL, CODUSUARIO INTEGER NOT NULL, DTHRCRIACAO TIMESTAMP NOT NULL, CONSTRAINT PK_CHATFASTIMPORTACAO PRIMARY KEY(CODCHATFASTIMPORTACAO), CONSTRAINT UNQ_CFIMPORTACAO_SHA256 UNIQUE(SHA256), CONSTRAINT FK_CFIMPORTACAO_USUARIO FOREIGN KEY(CODUSUARIO) REFERENCES USUARIO(CODUSUARIO)",
        ["CHATFASTRELATORIO"] = "CODCHATFASTRELATORIO BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, CHAVE VARCHAR(64) CHARACTER SET ASCII NOT NULL, SHA256 VARCHAR(64) CHARACTER SET ASCII NOT NULL, TIPO VARCHAR(10) CHARACTER SET ASCII NOT NULL, INICIO TIMESTAMP NOT NULL, FIM TIMESTAMP NOT NULL, COMPLETO SMALLINT NOT NULL, DTHRGERACAO TIMESTAMP NOT NULL, DTHRCRIACAO TIMESTAMP NOT NULL, DOCUMENTO BLOB SUB_TYPE TEXT CHARACTER SET UTF8 NOT NULL, CONSTRAINT PK_CHATFASTRELATORIO PRIMARY KEY(CODCHATFASTRELATORIO), CONSTRAINT UNQ_CFRELATORIO_CHAVE UNIQUE(CHAVE), CONSTRAINT CK_CFRELATORIO_COMPLETO CHECK(COMPLETO IN (0,1)), CONSTRAINT CK_CFRELATORIO_TIPO CHECK(TIPO IN ('diario','semanal')), CONSTRAINT CK_CFRELATORIO_PERIODO CHECK(FIM>INICIO)"
    };
    public static async Task MigrateAsync(IFirebirdConnectionFactory db, CancellationToken ct = default)
    {
        await using var c = await db.OpenConnectionAsync(ct);
        await using var tx = await c.BeginTransactionAsync(ct);
        foreach (var (name, ddl) in Definitions)
            if (await c.ExecuteScalarAsync<int>(new CommandDefinition("SELECT COUNT(*) FROM RDB$RELATIONS WHERE RDB$RELATION_NAME=@name", new { name }, tx, cancellationToken: ct)) == 0)
                await c.ExecuteAsync(new CommandDefinition($"CREATE TABLE {name} ({ddl})", transaction: tx, cancellationToken: ct));
        if (await c.ExecuteScalarAsync<int>(new CommandDefinition("SELECT COUNT(*) FROM RDB$RELATION_CONSTRAINTS WHERE RDB$CONSTRAINT_NAME='FK_CFRESPOSTA_IMPORTACAO'", transaction: tx, cancellationToken: ct)) == 0)
            await c.ExecuteAsync(new CommandDefinition("ALTER TABLE CHATFASTRESPOSTA ADD CONSTRAINT FK_CFRESPOSTA_IMPORTACAO FOREIGN KEY(CODCHATFASTIMPORTACAO) REFERENCES CHATFASTIMPORTACAO(CODCHATFASTIMPORTACAO)", transaction: tx, cancellationToken: ct));
        if (await c.ExecuteScalarAsync<int>(new CommandDefinition("SELECT COUNT(*) FROM RDB$INDICES WHERE RDB$INDEX_NAME='IX_CFRELATORIO_TIPO_GERACAO'", transaction: tx, cancellationToken: ct)) == 0)
            await c.ExecuteAsync(new CommandDefinition("CREATE INDEX IX_CFRELATORIO_TIPO_GERACAO ON CHATFASTRELATORIO(TIPO,DTHRGERACAO)", transaction: tx, cancellationToken: ct));
        await Validate(c, tx, ct);
        await tx.CommitAsync(ct);
    }
    public static async Task ValidateAsync(IFirebirdConnectionFactory db, CancellationToken ct = default)
    {
        await using var c = await db.OpenConnectionAsync(ct);
        await Validate(c, null, ct);
    }
    static async Task Validate(System.Data.IDbConnection c, System.Data.IDbTransaction? tx, CancellationToken ct)
    {
        foreach (var (name, ddl) in Definitions)
        {
            foreach (System.Text.RegularExpressions.Match field in System.Text.RegularExpressions.Regex.Matches(ddl, @"(?:^|, )([A-Z0-9]+) (BIGINT|INTEGER|SMALLINT|TIMESTAMP|VARCHAR\((\d+)\)|BLOB)[^,]*"))
            {
                var column = field.Groups[1].Value; var type = field.Groups[2].Value;
                var code = type switch { "BIGINT" => 16, "INTEGER" => 8, "SMALLINT" => 7, "TIMESTAMP" => 35, "BLOB" => 261, _ => 37 };
                var count = await c.ExecuteScalarAsync<int>(new CommandDefinition("SELECT COUNT(*) FROM RDB$RELATION_FIELDS R JOIN RDB$FIELDS F ON F.RDB$FIELD_NAME=R.RDB$FIELD_SOURCE WHERE R.RDB$RELATION_NAME=@name AND R.RDB$FIELD_NAME=@column AND F.RDB$FIELD_TYPE=@code AND (COALESCE(R.RDB$NULL_FLAG,0)=@required) AND (@length=0 OR F.RDB$CHARACTER_LENGTH=@length)",
                    new { name, column, code, required = field.Value.Contains("NOT NULL") ? 1 : 0, length = field.Groups[3].Success ? int.Parse(field.Groups[3].Value) : 0 }, tx, cancellationToken: ct));
                if (count != 1) throw new InvalidOperationException($"Schema ChatFast incompatível: {name}.{column}. Revise o alvo antes de migrar; nenhuma recriação automática é permitida.");
            }
            foreach (System.Text.RegularExpressions.Match constraint in System.Text.RegularExpressions.Regex.Matches(ddl, @"CONSTRAINT ([A-Z0-9_]+)"))
                if (await c.ExecuteScalarAsync<int>(new CommandDefinition("SELECT COUNT(*) FROM RDB$RELATION_CONSTRAINTS WHERE RDB$RELATION_NAME=@name AND RDB$CONSTRAINT_NAME=@constraint", new { name, constraint = constraint.Groups[1].Value }, tx, cancellationToken: ct)) != 1)
                    throw new InvalidOperationException($"Constraint ChatFast ausente em {name}.");
        }
        if (await c.ExecuteScalarAsync<int>(new CommandDefinition("SELECT COUNT(*) FROM RDB$RELATION_CONSTRAINTS WHERE RDB$RELATION_NAME='CHATFASTRESPOSTA' AND RDB$CONSTRAINT_NAME='FK_CFRESPOSTA_IMPORTACAO' AND RDB$CONSTRAINT_TYPE='FOREIGN KEY'", transaction: tx, cancellationToken: ct)) != 1)
            throw new InvalidOperationException("Vínculo de origem ChatFast ausente ou incompatível.");
        if (await c.ExecuteScalarAsync<int>(new CommandDefinition("SELECT COUNT(*) FROM RDB$INDICES WHERE RDB$RELATION_NAME='CHATFASTRELATORIO' AND RDB$INDEX_NAME='IX_CFRELATORIO_TIPO_GERACAO' AND COALESCE(RDB$INDEX_INACTIVE,0)=0", transaction: tx, cancellationToken: ct)) != 1)
            throw new InvalidOperationException("Índice de consulta ChatFast ausente ou inativo.");
    }
}
